// Slots 0-7 is everything the firmware has, so this needs no record of
// which ones were actually used. Clearing an empty slot is harmless.
const SLOTS = 8;

const messages = [];
for (let slot = 0; slot < SLOTS; slot++) {
    messages.push({
        action: 'glance_clock.clear_leds',
        payload: { slot: slot },
    });
}

// Returning an array of messages sends them all at once, which is why the
// delay node downstream is set to rate limit rather than to pause.
return [messages];
